using EventLensAI.Domain.Entities;using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Metadata.Builders;
namespace EventLensAI.Infrastructure.Persistence.Configurations;
internal sealed class EventBrandConfigurationConfiguration:IEntityTypeConfiguration<EventBrandConfiguration>{public void Configure(EntityTypeBuilder<EventBrandConfiguration>b){b.ToTable("event_brand_configurations");b.ConfigureBase();b.HasIndex(x=>x.EventId).IsUnique();b.Property(x=>x.EventDisplayName).HasMaxLength(200);b.Property(x=>x.PrimaryColor).HasMaxLength(7);b.Property(x=>x.SecondaryColor).HasMaxLength(7);b.Property(x=>x.AccentColor).HasMaxLength(7);b.Property(x=>x.FontFamily).HasMaxLength(100);b.Property(x=>x.ThemeMode).HasConversion<string>().HasMaxLength(20);b.Property(x=>x.ThemeOverridesJson).HasColumnType("nvarchar(max)");b.HasOne(x=>x.Event).WithOne().HasForeignKey<EventBrandConfiguration>(x=>x.EventId).OnDelete(DeleteBehavior.NoAction);b.HasOne(x=>x.BrandProfile).WithMany().HasForeignKey(x=>x.BrandProfileId).OnDelete(DeleteBehavior.NoAction);}}
internal sealed class EventExperienceSettingsConfiguration:IEntityTypeConfiguration<EventExperienceSettings>{public void Configure(EntityTypeBuilder<EventExperienceSettings>b){b.ToTable("event_experience_settings");b.ConfigureBase();b.HasIndex(x=>x.EventId).IsUnique();b.Property(x=>x.WelcomeTitle).HasMaxLength(200);b.Property(x=>x.WelcomeMessage).HasMaxLength(2000);b.Property(x=>x.CaptureMessage).HasMaxLength(1000);b.Property(x=>x.CompletionMessage).HasMaxLength(1000);b.Property(x=>x.GalleryTitle).HasMaxLength(200);b.Property(x=>x.GalleryDescription).HasMaxLength(2000);b.Property(x=>x.ConfigurationJson).HasColumnType("nvarchar(max)");b.HasOne(x=>x.Event).WithOne().HasForeignKey<EventExperienceSettings>(x=>x.EventId).OnDelete(DeleteBehavior.NoAction);}}
internal sealed class EventAssetConfiguration:IEntityTypeConfiguration<EventAsset>{public void Configure(EntityTypeBuilder<EventAsset>b){b.ToTable("event_assets");b.ConfigureBase();b.HasIndex(x=>x.EventId);b.Property(x=>x.StorageAssetId).HasMaxLength(500).IsRequired();b.Property(x=>x.AssetType).HasConversion<string>().HasMaxLength(30);b.Property(x=>x.DisplayName).HasMaxLength(200);b.Property(x=>x.ContentType).HasMaxLength(100);b.HasOne(x=>x.Event).WithMany().HasForeignKey(x=>x.EventId).OnDelete(DeleteBehavior.NoAction);}}
internal sealed class EventSponsorConfiguration:IEntityTypeConfiguration<EventSponsor>{public void Configure(EntityTypeBuilder<EventSponsor>b){b.ToTable("event_sponsors");b.ConfigureBase();b.HasIndex(x=>x.EventId);b.Property(x=>x.Name).HasMaxLength(200);b.Property(x=>x.Website).HasMaxLength(2048);b.HasOne(x=>x.Event).WithMany().HasForeignKey(x=>x.EventId).OnDelete(DeleteBehavior.NoAction);}}
